/* @autogenerated */
package net.civeira.phylax.feature.observe.alert;

import java.util.Map;

/**
 * A notice to deliver: an alert that fires or that is resolved.
 *
 * @param status {@code FIRING} or {@code RESOLVED}
 * @param targets emails or webhook URL of the rule
 * @param link absolute URL of the viewer that shows the problem
 * @param details variables for the templates and the webhook (origin, issue, metric...)
 */
public record AlertNotification(String alertUid, String ruleUid, String ruleName, String trigger,
    String status, String channel, String targets, String summary, String link,
    Map<String, Object> details) {

  public boolean firing() {
    return "FIRING".equals(status);
  }
}
